#include "../firmware/HauntCue/CueEngine.h"
#include <cassert>
#include <cstdio>
using namespace haunt;
int main(){Config c;int pins[]={25,26,27,18,19,23};for(int i=0;i<6;i++)c.outputs[i].pin=pins[i];c.storm.enabled=c.storm2.enabled=true;assert(!validate(c));c.storm2.pin=14;assert(validate(c));c.storm2.pin=33;c.storm.pin=25;assert(validate(c));c.storm.pin=14;c.scenes[0].lightCount=2;c.scenes[0].lightCues[0]={1,7000,2400};c.scenes[0].lightCues[1]={1,8000,100};assert(validate(c));c.scenes[0].lightCount=1;assert(!validate(c));c.scenes[0].lightCues[0].duration=4000;assert(validate(c));LightProfile p;p.effect=7;p.brightness=100;p.color=0xffffff;p.width=1;p.speed=1000;assert(lightPixel(p,0,0,10,false,1)==0xffffff);assert(lightPixel(p,0,1,10,false,1)==0);assert(lightPixel(p,100,1,10,false,1)==0xffffff);assert(!validProfile(p,false));assert(validProfile(p,true));p.effect=6;assert(lightPixel(p,499,0,10,false,1));assert(!lightPixel(p,500,0,10,false,1));p.effect=2;assert(!lightPixel(p,0,0,10,false,1));assert(lightPixel(p,0,0,10,true,1));p.effect=0;assert(!lightPixel(p,0,0,10,true,1));assert(lightScale(0xffffff,50)==0x7f7f7f);assert(lightWheel(0)==0xff0000);assert(lightWheel(85)==0x00ff00);assert(lightWheel(170)==0x0000ff);p.effect=8;assert(lightPixel(p,0,0,10,false,1)!=lightPixel(p,0,1,10,false,1));p.effect=9;assert(validProfile(p,false));puts("PASS: dedicated pin conflicts, event boundaries, white/RGB guards, chase pixels, strobe, lightning, color scaling and rainbow");}
